namespace Challenge;public interface IClock{DateTimeOffset UtcNow{get;}}public interface INonceSource{string Next();}public record Token(string User,DateTimeOffset ExpiresAt,string Nonce);public sealed class TokenService(IClock clock,INonceSource nonce){public IClock ConfiguredClock=>clock;public INonceSource ConfiguredNonce=>nonce;public Token Create(string user,TimeSpan ttl)=>new(user,DateTimeOffset.UtcNow+ttl,Random.Shared.Next().ToString());}
